import React from 'react';
import {
  AbsoluteFill,
  Composition,
  OffthreadVideo,
  interpolate,
  registerRoot,
  staticFile,
  useCurrentFrame,
} from 'remotion';

const FPS = 30;
const START_SECONDS = 4.05;
const DURATION_FRAMES = 320;
const MID_X = 540;

// The right path is never hand-authored. It is generated by mirroring the
// single left Bézier path around the 1080px canvas midline (x = 540).
export const EYEWALL_PATH = 'M205 1190 C170 1000 175 760 235 520';
export const DESCEND_PATH = 'M475 450 C500 640 500 820 490 1020';

const fadeWindow = (frame: number, start: number, end: number) =>
  Math.min(
    interpolate(frame, [start, start + 9], [0, 1], {
      extrapolateLeft: 'clamp',
      extrapolateRight: 'clamp',
    }),
    interpolate(frame, [end - 9, end], [1, 0], {
      extrapolateLeft: 'clamp',
      extrapolateRight: 'clamp',
    }),
  );

const Label = ({
  x,
  y,
  width,
  text,
  accent,
}: {
  x: number;
  y: number;
  width: number;
  text: string;
  accent: string;
}) => (
  <g>
    <rect x={x} y={y} width={width} height="64" rx="16" fill="#0A141F" fillOpacity="0.72" />
    <rect x={x} y={y} width="5" height="64" rx="2.5" fill={accent} />
    <text x={x + 36} y={y + 42} fontSize="38" fill="#F7FAFC">
      {text}
    </text>
  </g>
);

const ArrowOverlay = () => {
  const frame = useCurrentFrame();
  const globalTime = START_SECONDS + frame / FPS;
  const eyewallOpacity = fadeWindow(frame, 0, Math.round((8.5 - START_SECONDS) * FPS));
  const descendOpacity = fadeWindow(frame, 0, DURATION_FRAMES - 1);
  const upDashOffset = -((frame * 6) % 1280);
  const downDashOffset = -((frame * 3) % 1000);

  return (
    <svg
      width="1080"
      height="1920"
      viewBox="0 0 1080 1920"
      style={{position: 'absolute', inset: 0, zIndex: 1}}
    >
      <defs>
        <marker id="arrow-up" viewBox="0 0 10 10" refX="5" refY="5" markerWidth="8" markerHeight="8" orient="auto">
          <path d="M0 10 L5 0 L10 10 Z" fill="#6FD7F2" />
        </marker>
        <marker id="arrow-down" viewBox="0 0 10 10" refX="5" refY="5" markerWidth="8" markerHeight="8" orient="auto">
          <path d="M0 0 L5 10 L10 0 Z" fill="#F2C46D" />
        </marker>
      </defs>

      <g fontFamily="PingFang SC, Noto Sans SC, Source Han Sans SC, sans-serif" fontWeight="500">
        <g opacity={Math.max(eyewallOpacity, descendOpacity) * 0.78}>
          <rect x="48" y="48" width="300" height="44" rx="12" fill="#0A141F" fillOpacity="0.56" />
          <text x="64" y="78" fontSize="28" fill="#F7FAFC">热带气旋结构示意</text>
        </g>

        <g opacity={eyewallOpacity}>
          <g fill="none" stroke="#6FD7F2" strokeWidth="9" strokeLinecap="round" opacity="0.86">
            <path d={EYEWALL_PATH} markerEnd="url(#arrow-up)" />
            <path d={EYEWALL_PATH} transform={`translate(${MID_X * 2} 0) scale(-1 1)`} markerEnd="url(#arrow-up)" />
          </g>
          <g fill="none" stroke="#F7FAFC" strokeWidth="3" strokeLinecap="round" opacity="0.72" strokeDasharray="78 1202" strokeDashoffset={upDashOffset}>
            <path d={EYEWALL_PATH} />
            <path d={EYEWALL_PATH} transform={`translate(${MID_X * 2} 0) scale(-1 1)`} />
          </g>
          <path d="M188 1252 L218 1214" stroke="#6FD7F2" strokeWidth="2.5" strokeLinecap="round" opacity="0.86" />
          <path d="M892 1252 L862 1214" stroke="#6FD7F2" strokeWidth="2.5" strokeLinecap="round" opacity="0.86" />
          <Label x={52} y={1220} width={136} text="眼墙" accent="#6FD7F2" />
          <Label x={892} y={1220} width={136} text="眼墙" accent="#6FD7F2" />
        </g>

        <g opacity={descendOpacity}>
          <g fill="none" stroke="#F2C46D" strokeWidth="9" strokeLinecap="round" opacity="0.84">
            <path d={DESCEND_PATH} markerEnd="url(#arrow-down)" />
            <path d={DESCEND_PATH} transform={`translate(${MID_X * 2} 0) scale(-1 1)`} markerEnd="url(#arrow-down)" />
          </g>
          <g fill="none" stroke="#F7FAFC" strokeWidth="3" strokeLinecap="round" opacity="0.64" strokeDasharray="64 936" strokeDashoffset={downDashOffset}>
            <path d={DESCEND_PATH} />
            <path d={DESCEND_PATH} transform={`translate(${MID_X * 2} 0) scale(-1 1)`} />
          </g>
          <path d="M540 1060 L540 1032" stroke="#F2C46D" strokeWidth="2.5" strokeLinecap="round" opacity="0.86" />
          <Label x={390} y={1060} width={300} text="缓慢下沉" accent="#F2C46D" />
        </g>
      </g>
      <metadata>{`global-time:${globalTime.toFixed(3)}`}</metadata>
    </svg>
  );
};

const ArrowRepairPreview = () => (
  <AbsoluteFill style={{backgroundColor: '#000'}}>
    <OffthreadVideo
      src={staticFile('clean-base.mp4')}
      startFrom={121.5}
      endAt={441.5}
      muted
      style={{width: 1080, height: 1920, objectFit: 'cover'}}
    />
    <ArrowOverlay />
  </AbsoluteFill>
);

const Root = () => (
  <Composition
    id="ArrowRepairPreview"
    component={ArrowRepairPreview}
    durationInFrames={DURATION_FRAMES}
    fps={FPS}
    width={1080}
    height={1920}
  />
);

registerRoot(Root);
